import json, os, time
import boto3
sqs = boto3.client("sqs")
def handler(event, context):
    record = {"event": event, "handler_request_id": context.aws_request_id, "invoked_function_arn": context.invoked_function_arn, "received_unix": time.time()}
    sqs.send_message(QueueUrl=os.environ["QUEUE_URL"], MessageBody=json.dumps(record))
    return {"collected": True}
